## Why This Is Asked
Streaming data often requires maintaining a running statistic under insertions and deletions. The median is robust and a common interview target for dynamic data structures.

## Key Concepts
- Two-heap approach: keep lower half in a max-heap and upper half in a min-heap.
- Duplicates supported; lazy deletion via a delay map.
- Rebalancing invariant: size difference at most 1; median derived from heap tops.

## Code Example
```javascript
class MedianDS {
  constructor(){
    this.lo = new MaxHeap(); // lower half
    this.hi = new MinHeap(); // upper half
    this.delayed = new Map();
    this.sizeLo = 0;
    this.sizeHi = 0;
  }
  _cleanTop(h) {
    const top = h.peek();
    while (top !== null && this.delayed.get(top) > 0) {
      h.pop();
      this.delayed.set(top, this.delayed.get(top) - 1);
    }
  }
  add(x){
    if (this.sizeLo === 0 || x <= this.lo.peek()) {
      this.lo.push(x); this.sizeLo++;
    } else { this.hi.push(x); this.sizeHi++; }
    this._balance();
  }
  remove(x){
    const loTop = this.lo.peek();
    if (loTop !== null && x <= loTop) {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeLo--;
      if (x === loTop) this._cleanTop(this.lo);
    } else {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeHi--;
      this._cleanTop(this.hi);
    }
    this._balance();
  }
  _balance(){
    if (this.sizeLo > this.sizeHi + 1) {
      this.hi.push(this.lo.pop()); this.sizeLo--; this.sizeHi++;
    } else if (this.sizeHi > this.sizeLo) {
      this.lo.push(this.hi.pop()); this.sizeHi--; this.sizeLo++;
    }
    this._cleanTop(this.lo); this._cleanTop(this.hi);
  }
  getMedian(){
    if (this.sizeLo === 0) return null;
    if (this.sizeLo > this.sizeHi) return this.lo.peek();
    return (this.lo.peek() + this.hi.peek()) / 2;
  }
}
```

## Why This Is Asked
This question tests the ability to design a practical data structure and reason about block balancing in edit-heavy scenarios.

## Key Concepts
- **Sqrt decomposition**: Partition data into fixed-size blocks for efficient range queries
- **Per-block sums**: Enable O(1) block-level aggregation during rangeSum operations
- **Amortized balance**: Split/merge operations maintain block sizes within bounds, ensuring O(√n) amortized time per update
- **Edge-case handling**: Proper merge/split logic prevents pathological degradation

## Code Example
```javascript
class SqrtArray {
  constructor() {
    this.blocks = [];
    this.B = 2;
  }

  _getBlock(index) {
    let count = 0;
    for (const block of this.blocks) {
      if (index < count + block.length) return block;
      count += block.length;
    }
    throw new Error('Index out of bounds');
  }

  insertAt(index, value) {
    const block = this._getBlock(index);
    block.push(value);
    block.sum += value;
    if (block.length > 2 * this.B) this._split(block);
  }

  eraseAt(index) {
    const block = this._getBlock(index);
    block.splice(index, 1);
    block.sum -= value;
    if (block.length < this.B / 2) this._merge(block);
  }

  rangeSum(l, r) {
    let sum = 0;
    let count = 0;
    for (const block of this.blocks) {
      const blockStart = count;
      const blockEnd = count + block.length - 1;
      if (r < blockStart || l > blockEnd) { count += block.length; continue; }
      const start = Math.max(l, blockStart);
      const end = Math.min(r, blockEnd);
      if (start === blockStart && end === blockEnd) sum += block.sum;
      else for (let i = start; i <= end; i++) sum += block[i];
      count += block.length;
    }
    return sum;
  }

  _split(block) {
    const mid = Math.floor(block.length / 2);
    const newBlock = { arr: block.arr.splice(mid), sum: newBlock.arr.reduce((a,b)=>a+b,0) };
    block.sum = block.arr.reduce((a,b)=>a+b,0);
    const idx = this.blocks.indexOf(block);
    this.blocks.splice(idx + 1, 0, newBlock);
  }

  _merge(block) {
    const idx = this.blocks.indexOf(block);
    const neighbor = idx > 0 ? this.blocks[idx - 1] : this.blocks[idx + 1];
    const [small, big] = neighbor.length > block.length ? [block, neighbor] : [neighbor, block];
    big.arr.push(...small.arr);
    big.sum += small.sum;
    this.blocks.splice(this.blocks.indexOf(small), 1);
  }
}
```

